var tree = get_tree()
var scene = tree.current_scene
Engine.max_fps = 120
var set_vector = func(v: Vector2):
	for axis in [JOY_AXIS_RIGHT_X, JOY_AXIS_RIGHT_Y]:
		var event = InputEventJoypadMotion.new()
		event.device = 0
		event.axis = axis
		event.axis_value = v.x if axis == JOY_AXIS_RIGHT_X else v.y
		Input.parse_input_event(event)
var wait_frames = func(count: int):
	for frame in range(count):
		await tree.process_frame
set_vector.call(Vector2.ZERO)
await wait_frames.call(3)
var angles = [36.0,45.0,-36.0,-45.0,144.0,135.0,-144.0,-135.0]
var expected = ["R_FLARED","R_FLARED","R_HOOKERCUT","R_HOOKERCUT","L_FLARED","L_FLARED","L_HOOKERCUT","L_HOOKERCUT"]
var results = []
var passed = 0
for index in range(angles.size()):
	var angle = deg_to_rad(angles[index])
	var vector = Vector2(cos(angle), -sin(angle)) * 0.95
	for first in ["x","y"]:
		var before = scene.log_rows.size()
		set_vector.call(Vector2(vector.x,0.0) if first == "x" else Vector2(0.0,vector.y))
		await wait_frames.call(2)
		set_vector.call(vector)
		await wait_frames.call(3)
		set_vector.call(Vector2.ZERO)
		await wait_frames.call(3)
		var rows = scene.log_rows.slice(before)
		var ok = rows.size() == 1 and rows[0].split(",")[1] == expected[index]
		passed += int(ok)
		results.append({"intended_angle":angles[index],"first_axis":first,"expected":expected[index],"rows":rows,"passed":ok})
return {"passed":passed,"total":16,"cases":results,"scope":"Axis events deliberately separated by two render frames"}
